      "assessment": {
        "nobel_worthiness": "The first image of a black-hole shadow was a striking realization of an instrumentally demanding route to observing strong-gravity phenomena.",
        "attribution": "Falcke's early black-hole-shadow proposal and the leadership in creating and implementing Earth-scale millimetre interferometry are central.",
        "maturity": "The result has been reproduced across analyses and extended to a second black hole, with an enduring observing infrastructure.",
        "uncertainties": [
          "Attribution within the large EHT collaboration, including the essential correlation and imaging work, requires particular care."
        ]
      }
